@Test func inflateReadsEveryDeflateBlockType() {
  #expect(Inflate.zlib(Fixtures.emptyCompressed) == Fixtures.emptyRaw)
  #expect(Inflate.zlib(Fixtures.shortCompressed) == Fixtures.shortRaw)
  #expect(Inflate.zlib(Fixtures.storedCompressed) == Fixtures.storedRaw)
  #expect(Inflate.zlib(Fixtures.repetitiveCompressed) == Fixtures.repetitiveRaw)
}

@Test func inflateRejectsWhatIsntAZlibStream() {
  #expect(Inflate.zlib([]) == nil)
  #expect(Inflate.zlib([0x1F, 0x8B, 0x08, 0, 0, 0]) == nil)  // gzip, not zlib
  #expect(Inflate.zlib([0x78, 0xDA]) == nil)  // header only
  // A truncated stream stops rather than inventing data.
  #expect(Inflate.zlib(Array(Fixtures.repetitiveCompressed.prefix(40))) == nil)
}
